// Obtenemos los datos del mensaje
const text = $input.first().json.message.text;
const parts = text.split(' ');
const date = parts[1];
const time = parts[2];
const name = parts.slice(3).join(' ');

// Define tu zona horaria
const zone = 'America/Guayaquil'; // Asegúrate que sea la correcta

// Creamos el objeto de fecha para buscar
const startDateTime = DateTime.fromFormat(`${date} ${time}`, 'yyyy-MM-dd HH:mm', { zone });

// 3. Calculamos la hora de fin (1 hora después) usando el objeto que creamos
const endDateTime = startDateTime.plus({ hours: 1 });

// Devolvemos los datos necesarios para la búsqueda
return {
  name: name,
  summary: `Cita para ${name}`, // El título exacto que debe buscar
  startDateTime: startDateTime.toISO(),
  endDateTime: endDateTime.toISO()
};

const text = $input.first().json.message.text;

// "citas" es la 0, el nombre empieza en la 1
const name = text.split(' ').slice(1).join(' '); 

// Preparamos el término de búsqueda exacto para el título del evento
const searchTerm = `Cita para ${name}`;

return {
  name: name,
  searchTerm: searchTerm
};

// 1. Recibe los datos que vienen del nodo IF.
// Ya sabemos que no vienen vacíos, así que los procesamos directamente.
const citas = $items().map(item => item.json);

// 2. Obtenemos la fecha y hora actual para comparar.
const ahora = DateTime.now();

// 3. Filtramos para quedarnos solo con las citas futuras.
const citasFuturas = citas.filter(cita => {
  // Convertimos la "Fecha ISO" de la hoja de cálculo a un objeto de fecha real.
  const fechaCita = DateTime.fromISO(cita["Fecha ISO"]);
  // Devolvemos 'true' solo si la fecha de la cita es posterior a ahora.
  return fechaCita > ahora;
});

// 4. Verificamos si, después de filtrar, nos quedamos sin citas.
if (citasFuturas.length === 0) {
  // Tomamos el nombre del cliente de los datos originales para el mensaje.
  const nombreCliente = citas[0]["Nombre Cliente"];
  return {
    message: `Hola, ${nombreCliente}. 👋 Veo que tienes citas registradas en nuestro sistema, pero ninguna será en los próximos días.`
  };
}

// 5. Si SÍ hay citas futuras, construimos el mensaje de respuesta.
const nombreCliente = citasFuturas[0]["Nombre Cliente"];
let mensaje = `¡Hola, ${nombreCliente}! 👋 Aquí tienes un resumen de tus próximas citas:\n\n`;

for (const cita of citasFuturas) {
  // Usamos la columna "Fecha y hora" que ya tiene el formato amigable.
  mensaje += `🗓️ ${cita["Fecha y hora"]}\n`;
}

// Devolvemos el mensaje final listo para ser enviado.
return {
  message: mensaje
};

const text = $input.first().json.message.text.trim();
const parts = text.split(/\s+/);

// 1. Minimum parts: agendar fecha hora nombre...
if (parts.length < 4) {
  return { valid: false, error: "Faltan datos\\. Usa el formato exacto:\\n`agendar AAAA\\-MM\\-DD HH:MM Tu Nombre`\\n\\nEjemplo:\\n`agendar 2025\\-09\\-22 15:00 Ana García`" };
}

const date = parts[1];
const time = parts[2];
const name = parts.slice(3).join(' ').trim();

// 2. Date format YYYY-MM-DD
const dateRegex = /^\d{4}-(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01])$/;
if (!dateRegex.test(date)) {
  return { valid: false, error: `La fecha *${date}* no es válida\\.\nUsa el formato: \`AAAA\\-MM\\-DD\`\nEjemplo: \`2025\\-09\\-22\`` };
}

// 3. Time format HH:MM (24h)
const timeRegex = /^([01]\d|2[0-3]):[0-5]\d$/;
if (!timeRegex.test(time)) {
  return { valid: false, error: `La hora *${time}* no es válida\\.\nUsa formato 24h: \`HH:MM\`\nEjemplo: \`15:00\`` };
}

// 4. Valid calendar date (e.g. not 2025-02-30)
const zone = 'America/Guayaquil';
const startDateTime = DateTime.fromFormat(`${date} ${time}`, 'yyyy-MM-dd HH:mm', { zone });
if (!startDateTime.isValid) {
  return { valid: false, error: `La fecha *${date}* no existe en el calendario\\. Verifica el día del mes\\.` };
}

// 5. Not in the past
if (startDateTime < DateTime.now().setZone(zone)) {
  return { valid: false, error: `La fecha *${date} ${time}* ya pasó\\. Por favor elige una fecha y hora futura\\.` };
}

// 6. Business hours: Mon-Fri 07:00-19:00, Sat 07:00-13:00
const weekday = startDateTime.weekday; // 1=Mon ... 7=Sun
const hour = startDateTime.hour;
const minute = startDateTime.minute;
const timeInMin = hour * 60 + minute;
if (weekday === 7) {
  return { valid: false, error: "No atendemos los *domingos*\\. Elige un día de lunes a sábado\\." };
}
if (weekday === 6 && timeInMin > 13*60) {
  return { valid: false, error: "Los sábados atendemos hasta las *13:00*\\. Elige otro horario\\." };
}
if (timeInMin < 7*60 || timeInMin > 19*60) {
  return { valid: false, error: "Horario de atención: *lunes a viernes 07:00\\-19:00*, *sábados 07:00\\-13:00*\\." };
}

// 7. Name: at least 2 words, no numbers
if (!name || name.split(' ').filter(w => w.length > 0).length < 2) {
  return { valid: false, error: "Por favor escribe tu *nombre y apellido completos*\\.\nEjemplo: `agendar 2025\\-09\\-22 15:00 Ana García`" };
}
if (/\d/.test(name)) {
  return { valid: false, error: "El nombre no debe contener números\\. Escribe tu nombre completo\\." };
}

const endDateTime = startDateTime.plus({ hours: 1 });

return {
  valid: true,
  date, time, name,
  startDateTime: startDateTime.toISO(),
  endDateTime: endDateTime.toISO(),
  summary: `Cita para ${name} - Bot CIAP`
};

